
const $=id=>document.getElementById(id);const API='';
const landingPaths=['/','/landing','/home'];
const state={mode:location.pathname.includes('admin')?'admin':location.pathname.includes('kiosk')?'kiosk':location.pathname.includes('cashier')?'cashier':location.pathname.includes('delivery')?'delivery':(landingPaths.includes(location.pathname)?'landing':'consumer'),token:localStorage.getItem('ff_token')||'',user:null,stores:[],store:null,menu:[],categories:[],cat:'All',cart:JSON.parse(localStorage.getItem('ff_cart')||'{}'),config:{theme:{},features:{}},orders:[],visibleCount:6};
function toast(m){const t=$('toast');t.textContent=m;t.className='toast show';setTimeout(()=>t.className='toast',2600)}
async function api(path,opt={}){let r=await fetch(API+path,{headers:{'Content-Type':'application/json'},...opt});let txt=await r.text();let d;try{d=JSON.parse(txt)}catch{d={raw:txt}};if(!r.ok)throw new Error(d.detail||d.message||'Request failed');return d}
function money(n){return '₹'+Number(n||0).toFixed(0)}function calcSummary(vals){let subtotal=vals.reduce((a,x)=>a+x.qty*x.item.price,0),discount=0,taxes=[],taxTotal=0;let cfg=state.config.taxes||{enabled:true,lines:[]};if(cfg.enabled!==false){(cfg.lines||[]).forEach(t=>{if(t.enabled!==false){let rate=Number(t.rate||0),amt=Math.round((subtotal-discount)*rate)/100; if(rate||amt){taxes.push({label:t.label||'Tax',rate,amount:amt});taxTotal+=amt}}})}let total=Math.max(0,subtotal-discount+taxTotal);return{subtotal,discount,taxes,taxTotal,total}}function summaryHtml(sum,heading='Order Value'){return `<div class="card"><div class="between"><b>${heading}</b><b>${money(sum.subtotal)}</b></div>${sum.discount?`<div class="tax-line"><span>Discount</span><b>- ${money(sum.discount)}</b></div>`:''}${sum.taxes.map(t=>`<div class="tax-line"><span>${t.label} (${t.rate}%)</span><b>${money(t.amount)}</b></div>`).join('')}<div class="between" style="border-top:1px solid var(--line);padding-top:10px;margin-top:8px"><b>Total Payable</b><h2 style="margin:0">${money(sum.total)}</h2></div></div>`}function orderSummaryHtml(o){let taxes=Array.isArray(o.tax_breakdown)?o.tax_breakdown:safeJson(o.tax_breakdown);return `<div class="receipt-card card"><h3 style="margin-top:0">Order Receipt</h3><div class="between"><span>Order No.</span><b>${o.order_no}</b></div><div class="between muted"><span>Store</span><span>${o.store_name||''}</span></div><div class="receipt-items">${(o.items||[]).map(i=>`<div class="order-line"><span>${i.name}<br><span class="muted">${money(i.unit_price)} x ${i.quantity}</span></span><b>${money(i.line_total)}</b></div>`).join('')}</div><div class="tax-line"><span>Subtotal</span><b>${money(o.subtotal)}</b></div>${Number(o.discount||0)?`<div class="tax-line"><span>Discount</span><b>- ${money(o.discount)}</b></div>`:''}${(taxes||[]).map(t=>`<div class="tax-line"><span>${t.label} (${t.rate}%)</span><b>${money(t.amount)}</b></div>`).join('')}<div class="between" style="border-top:1px solid var(--line);padding-top:10px;margin-top:8px"><b>Total Paid</b><h2 style="margin:0">${money(o.total)}</h2></div><p class="muted">Payment: ${o.payment_method||''} • ${o.payment_status||''}</p></div>`}function cartQty(){return Object.values(state.cart).reduce((a,b)=>a+Number(b.qty||0),0)}function saveCart(){localStorage.setItem('ff_cart',JSON.stringify(state.cart));updateCartBadge()}function updateCartBadge(){let b=$('cartBadge');if(b)b.textContent=cartQty()}function currentStoreId(){return state.store?.id||1}
function applyTheme(t){if(!t)return;document.documentElement.style.setProperty('--primary',t.primary_color||'#12103f');document.documentElement.style.setProperty('--secondary',t.secondary_color||'#f4b942');document.documentElement.style.setProperty('--accent',t.accent_color||'#24a36a');document.documentElement.style.setProperty('--bg',t.background_color||'#f6f7fb');document.title=t.app_name||'Truflux FoodFlow'}
function bannerHtml(context='app'){let t=state.config.theme||{};let img=context==='kiosk'?(t.kiosk_banner_url||t.ad_banner_url):(t.app_banner_url||t.ad_banner_url);let title=t.ad_banner_title||"Today's Specials";let text=t.ad_banner_text||'Fresh meals, fast ordering and QR pickup.';return `<div class="promo-banner ${img?'has-img':''}" ${img?`style="background-image:linear-gradient(90deg,rgba(18,16,63,.78),rgba(18,16,63,.2)),url('${img}')"`:''}><div><span class="badge ok">Latest Offer</span><h1>${title}</h1><p>${text}</p></div></div>`}
function profileNavIcon(){let p=state.user?.photo_url||'';return p?`<img class="nav-avatar" src="${p}" onerror="this.outerHTML='<span>👤</span>'">`:'<span>👤</span>'}

function goHome(){localStorage.removeItem('ff_cart'); location.href='/'}
function ensureHomeButton(){
  const old=document.getElementById('globalHomeButton');
  if(state.mode==='landing'){ if(old) old.remove(); return; }
  if(!old){
    const b=document.createElement('button');
    b.id='globalHomeButton';
    b.className='home-fab';
    b.type='button';
    b.innerHTML='⌂ Home';
    b.onclick=goHome;
    document.body.appendChild(b);
  }
}
function renderLanding(){let t=state.config.theme||{};document.getElementById('root').innerHTML=`<div class="landing-shell"><div class="landing-card"><div class="brand-lockup"><div class="brand-mark">T</div><h1>${t.app_name||'Truflux FoodFlow'}</h1><p>Bangalore, Karnataka</p></div>${bannerHtml('app')}<div class="landing-options"><button class="landing-option" onclick="startMode('/app')"><b>📱 Mobile App</b><span>Login and experience consumer ordering, payment and QR token.</span></button><button class="landing-option" onclick="startMode('/cashier')"><b>🧾 Cashier POS</b><span>Login to open the iPad-style pictorial walk-in billing screen.</span></button><button class="landing-option" onclick="startMode('/kiosk')"><b>🖥️ Kiosk</b><span>Login to launch touchscreen self-order and QR receipt mode.</span></button><button class="landing-option" onclick="startMode('/delivery')"><b>✅ Delivery / Pickup</b><span>Scan or enter the customer's receipt QR and mark the order fulfilled.</span></button></div><button class="admin-link-button" onclick="startMode('/admin')">Admin Configuration Login</button><p class="hint" style="text-align:center;margin-top:12px">Each demo mode starts with mobile + OTP login. Session then persists until logout.</p></div></div>`}
function startMode(path){localStorage.removeItem('ff_token');localStorage.removeItem('ff_cart');location.href=path}

async function boot(){state.config=await api('/api/config');applyTheme(state.config.theme);if(state.mode==='landing'){renderLanding();return}if(state.token){try{state.user=(await api('/api/me?token='+encodeURIComponent(state.token))).user}catch{localStorage.removeItem('ff_token');state.token=''}}if(!state.token){renderLogin();return}await loadStores();if(state.mode==='admin') renderAdminShell(); else if(state.mode==='kiosk') renderKiosk(); else if(state.mode==='cashier') renderCashier(); else if(state.mode==='delivery') renderDelivery(); else renderConsumer();}
function renderLogin(){document.body.className='';document.getElementById('root').innerHTML=`<div class="login-bg"><div class="phone-frame"><div class="brand-lockup"><div class="brand-mark">T</div><h1>${state.config.theme.app_name||'Truflux FoodFlow'}</h1><p>Bangalore, Karnataka</p></div><div class="login-card"><h2 style="margin:0;color:var(--primary)">${state.mode==='admin'?'Admin Login':state.mode==='kiosk'?'Kiosk Start':state.mode==='cashier'?'Cashier Login':state.mode==='delivery'?'Delivery Login':'Login'}</h2><p class="hint">Enter your mobile number. The OTP will appear as six separate digits, like a mobile app login screen.</p><label>Mobile Number</label><input id="loginMobile" inputmode="numeric" maxlength="10" placeholder="9999999999" value="9999999999"><button class="btn secondary" id="sendOtpBtn" style="margin-top:14px" onclick="sendOtp()">Send OTP</button><div id="otpBlock" class="hidden"><div class="between" style="margin-top:16px"><label style="margin:0">Enter OTP</label><button class="link-btn" onclick="resetOtp()">Change number</button></div><div class="otp-box-row" id="otpBoxes">${[0,1,2,3,4,5].map(i=>`<input class="otp-digit" id="otp${i}" inputmode="numeric" maxlength="1" autocomplete="one-time-code" oninput="otpDigitInput(${i})" onkeydown="otpKeyDown(event,${i})" onpaste="otpPaste(event)">`).join('')}</div><button class="btn" style="margin-top:14px" onclick="verifyOtp()">Verify & Login</button><p class="hint" style="text-align:center">Demo OTP: 123456</p></div></div></div></div>`}
async function sendOtp(){let m=$('loginMobile').value.trim();if(!m)return toast('Enter mobile number');if(m.length<10)return toast('Enter valid 10 digit mobile number');await api('/api/auth/send-otp',{method:'POST',body:JSON.stringify({mobile:m})});$('otpBlock').classList.remove('hidden');$('sendOtpBtn').textContent='Resend OTP';setTimeout(()=>{$('otp0')?.focus()},80);toast('OTP sent to mobile. Demo OTP is 123456')}
function resetOtp(){$('loginMobile').focus();$('otpBlock').classList.add('hidden');$('sendOtpBtn').textContent='Send OTP';[0,1,2,3,4,5].forEach(i=>{let e=$('otp'+i); if(e)e.value=''})}
function otpDigitInput(i){let e=$('otp'+i);e.value=(e.value||'').replace(/\D/g,'').slice(0,1);if(e.value&&i<5)$('otp'+(i+1)).focus()}
function otpKeyDown(ev,i){if(ev.key==='Backspace'&&!$('otp'+i).value&&i>0){$('otp'+(i-1)).focus()} if(ev.key==='ArrowLeft'&&i>0){ev.preventDefault();$('otp'+(i-1)).focus()} if(ev.key==='ArrowRight'&&i<5){ev.preventDefault();$('otp'+(i+1)).focus()}}
function otpPaste(ev){ev.preventDefault();let txt=(ev.clipboardData||window.clipboardData).getData('text').replace(/\D/g,'').slice(0,6);txt.split('').forEach((d,i)=>{$('otp'+i).value=d});$('otp'+Math.min(txt.length,5)).focus()}
function otpValue(){return [0,1,2,3,4,5].map(i=>($('otp'+i)?.value||'')).join('')}
async function verifyOtp(){let mobile=$('loginMobile').value.trim(),otp=otpValue();if(otp.length!==6)return toast('Enter the 6 digit OTP');let d=await api('/api/auth/verify',{method:'POST',body:JSON.stringify({mobile,otp})});state.token=d.token;state.user=d.user;localStorage.setItem('ff_token',d.token);await boot()}
async function logout(){await api('/api/logout?token='+encodeURIComponent(state.token),{method:'POST'}).catch(()=>{});localStorage.removeItem('ff_token');localStorage.removeItem('ff_cart');state.token='';state.cart={};renderLogin()}
async function loadStores(){let d=await api('/api/stores');state.stores=d.stores||[];let preferred=state.user?.preferred_store_id;state.store=state.stores.find(s=>s.id==preferred)||state.stores[0]||null;await loadMenu()}
async function loadMenu(){let d=await api('/api/menu?store_id='+currentStoreId());state.menu=d.items||[];state.categories=['All',...(d.categories||[])];}
function storeOneLine(){if(!state.store)return 'No store selected';return `${state.store.name} • ${state.store.area}, ${state.store.city}`}
function storeSelector(){if(state.stores.length<=1)return `<div class="store-line">📍 ${storeOneLine()}</div>`;return `<div class="store-line">📍 <select onchange="changeStore(this.value)">${state.stores.map(s=>`<option value="${s.id}" ${state.store&&s.id==state.store.id?'selected':''}>${s.name} — ${s.area}, ${s.city}</option>`).join('')}</select></div>`}
async function changeStore(id){state.store=state.stores.find(s=>s.id==id)||state.stores[0];await loadMenu();renderMenu();updateStoreLine()}
function updateStoreLine(){let e=$('storeLine');if(e)e.innerHTML=storeSelector().replace('<div class="store-line">','').replace('</div>','')}
function renderConsumer(){document.getElementById('root').innerHTML=`<main class="mobile-shell"><header class="app-header"><div class="top-title"><h2>${state.config.theme.app_name||'FoodFlow'}</h2><button class="cart-chip" onclick="showTab('cart')">🛒<span class="cart-count" id="cartBadge">0</span></button></div><div id="storeLine">${storeSelector()}</div></header><section class="content" id="mobileContent"><div id="menu" class="screen active"></div><div id="cart" class="screen"></div><div id="receipt" class="screen"></div><div id="orders" class="screen"></div><div id="profile" class="screen"></div></section><nav class="bottom-nav"><button id="nav-menu" class="nav-btn active" onclick="showTab('menu')"><span>🍽️</span><span>Menu</span></button><button id="nav-cart" class="nav-btn" onclick="showTab('cart')"><span>🛒</span><span>Cart</span></button><button id="nav-orders" class="nav-btn" onclick="showTab('orders')"><span>🎟️</span><span>Orders</span></button><button id="nav-profile" class="nav-btn" onclick="showTab('profile')">${profileNavIcon()}<span>Profile</span></button></nav></main>`;updateCartBadge();renderMenu();renderCart();renderProfile();setupMenuInfiniteScroll()}
function showScreen(t){document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.nav-btn').forEach(x=>x.classList.remove('active'));$(t)?.classList.add('active')}function showTab(t){showScreen(t);$('nav-'+t)?.classList.add('active');if(t==='orders')renderOrders();if(t==='profile')renderProfile();if(t==='cart')renderCart();if(t==='menu')renderMenu()}
function renderMenu(){let cats=state.categories.map(c=>`<button class="pill ${state.cat===c?'active':''}" onclick="state.cat='${c}';state.visibleCount=6;renderMenu()">${c}</button>`).join('');let all=state.menu.filter(i=>state.cat==='All'||i.category===state.cat);let items=all.slice(0,state.visibleCount);$('menu').innerHTML=`${bannerHtml('app')}<div class="category-row">${cats}</div><div class="menu-grid compact-menu-grid">${items.map(itemCard).join('')}</div>${!items.length?'<div class="empty">No menu items available.</div>':''}${state.visibleCount<all.length?'<div id="loadMoreSentinel" class="load-more">Loading more as you scroll…</div>':''}`;setupMenuInfiniteScroll()}
function itemCard(i){let inCart=state.cart[i.id]?.qty||0;return `<button class="square-menu-tile compact-tile tap-tile ${i.out_of_stock?'disabled-note':''}" onclick="addQty(${i.id},1)" aria-label="Add ${i.name}"><div class="tile-bg">${i.image_url?`<img class="square-img" src="${i.image_url}" loading="lazy" onerror="this.remove();this.parentElement.classList.add('no-img')">`:''}<span id="tileBadge-${i.id}" class="tile-cart-badge ${inCart?'':'hidden'}">${inCart}</span>${i.out_of_stock?'<span class="tile-stock">Out</span>':''}</div><div class="tile-overlay"><b>${i.name}</b><strong>${money(i.price)}</strong></div></button>`}
function recommendations(i){let ids=[...(safeJson(i.cross_sell_ids)),...(safeJson(i.upsell_ids))].slice(0,2);let names=ids.map(id=>state.menu.find(x=>x.id==id)?.name).filter(Boolean);return names.length?`<div class="muted" style="margin-top:7px">AI suggestion: ${names.join(', ')}</div>`:''}function safeJson(x){if(Array.isArray(x))return x;try{return JSON.parse(x||'[]')}catch{return []}}
function updateTileBadge(id){let b=$('tileBadge-'+id);if(!b)return;let q=state.cart[id]?.qty||0;b.textContent=q;b.classList.toggle('hidden',!q)}function setupMenuInfiniteScroll(){let sentinel=$('loadMoreSentinel');if(!sentinel||state.mode!=='consumer')return;if(window.menuObserver)window.menuObserver.disconnect();window.menuObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){let old=state.visibleCount;state.visibleCount+=6;if(state.visibleCount!==old)renderMenu()}},{root:$('mobileContent')||null,rootMargin:'180px'});window.menuObserver.observe(sentinel)}function addQty(id,delta){let item=state.menu.find(x=>x.id===id);if(!item)return;if(item.out_of_stock)return toast('Item out of stock');let q=(state.cart[id]?.qty||0)+delta;if(q<=0)delete state.cart[id];else state.cart[id]={item,qty:q};saveCart();let active=document.querySelector('.screen.active')?.id;if(state.mode==='consumer'){updateTileBadge(id);if(active==='cart')renderCart()}else if(state.mode==='kiosk'){renderKioskMenu()}else if(state.mode==='cashier'){renderCashierBody()}}
function renderCart(){let vals=Object.values(state.cart),sum=calcSummary(vals);$('cart').innerHTML=`<div class="card"><h2 style="margin:0">Cart</h2><p class="muted">${cartQty()} dishes added</p></div>${vals.length?vals.map(x=>`<div class="card"><div class="between"><b>${x.item.name}</b><b>${money(x.qty*x.item.price)}</b></div><div class="between muted"><span>${money(x.item.price)} each</span><div class="qty"><button onclick="addQty(${x.item.id},-1)">−</button><b>${x.qty}</b><button onclick="addQty(${x.item.id},1)">+</button></div></div></div>`).join('')+summaryHtml(sum,'Order Value')+`<div class="card"><div class="pay-panel"><b>Payment Gateway</b><p class="muted">Demo interface: UPI / Card / Wallet. Order goes to kitchen after payment confirmation.</p><select id="payMethod"><option>UPI</option><option>Card</option><option>Wallet</option></select><button class="btn accent" style="margin-top:12px" onclick="placeOrder('mobile')">Pay & Place Order</button></div></div>`:'<div class="empty">Your cart is empty. Add dishes from the menu.</div>'}`;updateCartBadge()}
async function placeOrder(source='mobile'){let vals=Object.values(state.cart);if(!vals.length)return toast('Cart is empty');let body={token:source==='kiosk'?null:state.token,mobile:source==='kiosk'?($('kioskMobile')?.value||'GUEST'):undefined,store_id:currentStoreId(),source,items:vals.map(x=>({item_id:x.item.id,quantity:x.qty,customisation:''})),payment_method:$('payMethod')?.value||'UPI'};let o=(await api('/api/orders',{method:'POST',body:JSON.stringify(body)})).order;let paid=(await api('/api/payments/confirm',{method:'POST',body:JSON.stringify({order_id:o.id,payment_status:'success'})})).order;state.lastOrder=paid;state.cart={};saveCart();if(source==='mobile'){renderReceiptPage(paid);renderCart();showScreen('receipt')}else if(source==='cashier')renderCashierConfirmation(paid);else renderKioskConfirmation(paid)}
function renderReceiptPage(o){$('receipt').innerHTML=`<div class="card hero"><h1 style="margin:0">Payment Confirmed</h1><p>Your order has been placed. Show this receipt QR at pickup.</p></div>${orderQrCard(o,true)}<div class="grid2"><button class="btn secondary" onclick="showTab('menu')">Back to Menu</button><button class="btn ghost" onclick="showTab('orders')">Order History</button></div>`}
function orderQrCard(o,actions=false){return `<div class="card"><div class="between"><b>${o.order_no}</b><span class="badge ok">Paid</span></div><p class="muted">${o.store_name} • ${o.order_status}</p><div class="qrbox"><img class="proper-qr" src="/api/orders/${o.id}/qr.png?v=${encodeURIComponent(o.order_no)}" alt="QR for ${o.order_no}"><p class="muted" style="word-break:break-all">QR: ${o.order_no}</p></div>${orderSummaryHtml(o)}${actions?`<div class="grid2"><button class="btn secondary small" onclick="saveReceipt(${o.id})">Download Receipt</button><button class="btn ghost small" onclick="shareQR('${o.order_no}')">Share QR</button><button class="btn small" onclick="printReceipt(${o.id})">Print Receipt</button></div>`:''}</div>`}
function qrPattern(token){let h=0;for(let i=0;i<token.length;i++)h=(h*31+token.charCodeAt(i))>>>0;let html='';for(let i=0;i<625;i++){let on=((h+i*17+(i%7)*13)%11)<5 || (i<5||i>619||i%25<5||i%25>19&&i<125);html+=`<i style="background:${on?'#000':'#fff'}"></i>`}return html}
function loadImage(src){return new Promise((resolve,reject)=>{let img=new Image();img.crossOrigin='anonymous';img.onload=()=>resolve(img);img.onerror=reject;img.src=src})}
async function saveReceipt(id){let o=(await api('/api/orders/'+id)).order;let taxes=Array.isArray(o.tax_breakdown)?o.tax_breakdown:safeJson(o.tax_breakdown);let c=document.createElement('canvas'),ctx=c.getContext('2d');c.width=760;c.height=1180;ctx.fillStyle='#ffffff';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#12103f';ctx.font='bold 36px Arial';ctx.textAlign='center';ctx.fillText('Truflux FoodFlow',c.width/2,56);ctx.font='20px Arial';ctx.fillText(o.store_name||'',c.width/2,88);ctx.fillStyle='#111827';ctx.font='bold 26px Arial';ctx.fillText('QR Order Receipt',c.width/2,130);ctx.textAlign='left';ctx.font='18px Arial';ctx.fillText('Order No: '+o.order_no,50,170);ctx.fillText('Source: '+(o.source||''),50,198);ctx.fillText('Payment: '+(o.payment_method||'')+' • '+(o.payment_status||''),50,226);let qr=await loadImage('/api/orders/'+o.id+'/qr.png?v='+encodeURIComponent(o.order_no));ctx.drawImage(qr,255,250,250,250);ctx.fillStyle='#4b5563';ctx.font='13px Arial';ctx.textAlign='center';wrap(ctx,'QR Order No: '+o.order_no,90,525,580,18);ctx.textAlign='left';let yy=590;ctx.fillStyle='#111827';ctx.font='bold 20px Arial';ctx.fillText('Items',50,yy);yy+=24;ctx.strokeStyle='#d1d5db';ctx.beginPath();ctx.moveTo(50,yy);ctx.lineTo(710,yy);ctx.stroke();yy+=22;ctx.font='17px Arial';(o.items||[]).forEach(i=>{ctx.fillStyle='#111827';wrap(ctx,i.name,50,yy,380,20);ctx.textAlign='right';ctx.fillText(String(i.quantity),530,yy);ctx.fillText(money(i.unit_price),610,yy);ctx.fillText(money(i.line_total),710,yy);ctx.textAlign='left';yy+=34});yy+=10;ctx.strokeStyle='#d1d5db';ctx.beginPath();ctx.moveTo(50,yy);ctx.lineTo(710,yy);ctx.stroke();yy+=30;function row(label,val,bold=false){ctx.font=(bold?'bold ':'')+'18px Arial';ctx.fillStyle='#111827';ctx.textAlign='left';ctx.fillText(label,50,yy);ctx.textAlign='right';ctx.fillText(val,710,yy);ctx.textAlign='left';yy+=30}row('Subtotal',money(o.subtotal));if(Number(o.discount||0))row('Discount','- '+money(o.discount));(taxes||[]).forEach(t=>row((t.label||'Tax')+' ('+(t.rate||0)+'%)',money(t.amount)));yy+=8;ctx.fillStyle='#12103f';ctx.fillRect(40,yy-24,680,56);ctx.fillStyle='#fff';ctx.font='bold 22px Arial';ctx.fillText('Total Paid',60,yy+12);ctx.textAlign='right';ctx.fillText(money(o.total),700,yy+12);ctx.textAlign='left';yy+=70;ctx.fillStyle='#4b5563';ctx.font='15px Arial';wrap(ctx,'This QR receipt is valid for pickup validation. Please show the QR code at the counter. Duplicate pickup is not allowed.',50,yy,660,20);let a=document.createElement('a');a.href=c.toDataURL('image/png');a.download=o.order_no+'-receipt.png';a.click()}function saveQR(token,no){toast('Receipt download now includes QR, order summary, quantity, price and taxes.')}
function wrap(ctx,text,x,y,max,l){let words=text.split('|'),line='';for(const w of words){let t=line+w+' ';if(ctx.measureText(t).width>max){ctx.fillText(line,x,y);line=w+' ';y+=l}else line=t}ctx.fillText(line,x,y)}
async function shareQR(token){if(navigator.share)await navigator.share({title:'FoodFlow QR',text:token}).catch(()=>{});else{await navigator.clipboard.writeText(token);toast('QR copied')}}async function printReceipt(id){let o=(await api('/api/orders/'+id)).order;let w=window.open('','_blank','width=420,height=760');w.document.write(`<html><head><title>${o.order_no}</title><style>body{font-family:Arial;margin:18px 18px 92px;color:#111}.center{text-align:center}.qrimg{width:220px;height:220px;margin:12px auto;display:block}.line{display:flex;justify-content:space-between;border-bottom:1px dashed #aaa;padding:6px 0}h2,h3{margin:6px 0}.muted{color:#666;font-size:12px}.done-bar{position:fixed;left:0;right:0;bottom:0;background:#fff;border-top:1px solid #ddd;padding:12px 18px;box-shadow:0 -8px 24px rgba(0,0,0,.08)}.done-btn{width:100%;border:0;border-radius:14px;background:#12103f;color:#fff;font-weight:800;font-size:16px;padding:14px}@media print{.done-bar{display:none}body{margin:18px}}</style></head><body><div class=center><h2>Truflux FoodFlow</h2><p>${o.store_name||''}</p><img class=qrimg src="/api/orders/${o.id}/qr.png?v=${encodeURIComponent(o.order_no)}"><p class=muted>QR Order No: ${o.order_no}</p></div>${receiptPlainHtml(o)}<div class=done-bar><button class=done-btn onclick="window.close(); if(!window.closed){location.href='/'}">Done</button></div><script>setTimeout(()=>window.print(),300)<\/script></body></html>`);w.document.close()}function receiptPlainHtml(o){let taxes=Array.isArray(o.tax_breakdown)?o.tax_breakdown:safeJson(o.tax_breakdown);return `<h3>Receipt ${o.order_no}</h3>${(o.items||[]).map(i=>`<div class=line><span>${i.name} x ${i.quantity}</span><b>${money(i.line_total)}</b></div>`).join('')}<div class=line><span>Subtotal</span><b>${money(o.subtotal)}</b></div>${(taxes||[]).map(t=>`<div class=line><span>${t.label} (${t.rate}%)</span><b>${money(t.amount)}</b></div>`).join('')}<div class=line><b>Total Paid</b><h3>${money(o.total)}</h3></div><p class=muted>Payment: ${o.payment_method||''} • ${o.payment_status||''}</p>`}
async function renderOrders(){let d=await api('/api/my-orders?token='+encodeURIComponent(state.token));$('orders').innerHTML=`<div class="card"><h2 style="margin:0">Orders</h2><p class="muted">Tap an order to view receipt, QR and full item details.</p></div>`+(d.orders.length?d.orders.map(orderListCard).join(''):'<div class="empty">No orders yet.</div>')}
function orderListCard(o){let itemCount=(o.items||[]).reduce((a,i)=>a+Number(i.quantity||0),0);let dt=(o.created_at||'').replace('T',' ').slice(0,16);return `<button class="order-list-card" onclick="showOrderDetails(${o.id})"><div><b>${o.order_no}</b><p>${o.store_name||''} • ${dt}</p></div><div class="order-list-right"><b>${money(o.total)}</b><span>${itemCount} dishes</span><em>${o.order_status||''}</em></div></button>`}
async function showOrderDetails(id){let o=(await api('/api/orders/'+id)).order;$('orders').innerHTML=`<div class="card"><button class="btn ghost small" style="width:auto" onclick="renderOrders()">← Back to Orders</button></div>${orderQrCard(o,true)}`}
function renderProfile(){let u=state.user||{};let photo=u.photo_url||'';$('profile').innerHTML=`<div class="card"><div class="row"><img id="profPreview" class="profile-photo" src="${photo}" onerror="this.src='';this.style.display='none'"><div><h2 style="margin:0">Profile</h2><p class="muted">Signed in until logout</p></div></div><label>Name</label><input id="profName" value="${u.name||''}"><label>Email</label><input id="profEmail" value="${u.email||''}"><label>Upload Photograph</label><input id="profPhotoFile" type="file" accept="image/*" onchange="previewProfilePhoto()"><p class="hint">Upload a profile photograph from the phone gallery or camera. The prototype stores the image locally in SQLite as an encoded image.</p><label>Photo URL / Stored Image</label><input id="profPhoto" value="${photo}" placeholder="Upload photo or paste image URL"><label>Address</label><textarea id="profAddress">${u.address||''}</textarea><label>Dietary Preferences</label><input id="profDiet" value="${u.dietary_preferences||''}"><button class="btn secondary" style="margin-top:12px" onclick="saveProfile()">Save Profile</button><button class="btn ghost" style="margin-top:10px" onclick="logout()">Logout</button></div>`;if(!photo&&$('profPreview'))$('profPreview').style.display='none'}
async function previewProfilePhoto(){let img=await fileToDataUrl($('profPhotoFile'));if(img){$('profPhoto').value=img;let p=$('profPreview');p.src=img;p.style.display='block'}}
async function saveProfile(){let uploaded=await fileToDataUrl($('profPhotoFile'));let photo=uploaded||$('profPhoto').value;let d=await api('/api/profile',{method:'POST',body:JSON.stringify({token:state.token,name:$('profName').value,email:$('profEmail').value,photo_url:photo,address:$('profAddress').value,dietary_preferences:$('profDiet').value,preferred_store_id:currentStoreId()})});state.user=d.user;toast('Profile saved with photograph');renderProfile()}
async function renderKiosk(){document.getElementById('root').innerHTML=`<div class="kiosk-shell"><main class="mobile-shell"><header class="app-header"><div class="top-title"><h2>Kiosk Ordering</h2><button class="cart-chip" onclick="showKioskCart()">🛒<span class="cart-count" id="cartBadge">0</span></button></div><div id="storeLine">${storeSelector()}</div></header><section class="content"><div id="kioskBody"></div></section></main></div>`;updateCartBadge();renderKioskMenu()}
function renderKioskMenu(){let cats=state.categories.map(c=>`<button class="pill ${state.cat===c?'active':''}" onclick="state.cat='${c}';renderKioskMenu()">${c}</button>`).join('');let items=state.menu.filter(i=>state.cat==='All'||i.category===state.cat);$('kioskBody').innerHTML=`${bannerHtml('kiosk')}<div class="category-row">${cats}</div><div class="kiosk-menu-grid compact-menu-grid">${items.map(itemCard).join('')}</div>${!items.length?'<div class="empty">No menu items available for this store. Use Admin → Create Test Data.</div>':''}<button class="btn big-action" onclick="showKioskCart()">View Cart (${cartQty()})</button>`}
function showKioskCart(){let vals=Object.values(state.cart),sum=calcSummary(vals);$('kioskBody').innerHTML=`<div class="card"><h2>Kiosk Cart</h2><p class="muted">${cartQty()} dishes added</p></div>${vals.map(x=>`<div class="card"><div class="between"><b>${x.item.name}</b><b>x${x.qty}</b></div><p class="muted">${money(x.item.price)} each • ${money(x.qty*x.item.price)}</p></div>`).join('')}${summaryHtml(sum,'Order Value')}<div class="card"><label>Mobile number for QR image / receipt</label><input id="kioskMobile" placeholder="Optional"><label>Payment Method</label><select id="payMethod"><option>UPI QR</option><option>Card Terminal</option><option>Wallet</option></select><button class="btn accent" style="margin-top:12px" onclick="placeOrder('kiosk')">Pay & Generate QR Receipt</button><button class="btn ghost" style="margin-top:10px" onclick="renderKioskMenu()">Back to Menu</button></div>`}
function renderKioskConfirmation(o){$('kioskBody').innerHTML=`<div class="card hero"><h1>Order Confirmed</h1><p>Show or print this QR at pickup.</p></div>${orderQrCard(o,true)}<button class="btn secondary" onclick="printReceipt(${o.id})">Print QR Receipt</button><button class="btn ghost" style="margin-top:10px" onclick="state.cart={};saveCart();renderKioskMenu()">Start New Order</button>`}
async function renderCashier(){document.getElementById('root').innerHTML=`<div class="pos-shell"><div class="card pos-top"><div><h1 style="margin:0;color:var(--primary)">Cashier / Walk-in POS</h1><p class="muted">iPad-style fast transaction screen with pictorial menu.</p></div><a class="btn ghost" style="width:auto;text-decoration:none" href="/admin">Admin</a></div><div class="card">${storeSelector()}</div><div id="cashierBody"></div></div>`;renderCashierBody()}
function renderCashierBody(){let cats=state.categories.map(c=>`<button class="pill ${state.cat===c?'active':''}" onclick="state.cat='${c}';renderCashierBody()">${c}</button>`).join('');let items=state.menu.filter(i=>state.cat==='All'||i.category===state.cat);let vals=Object.values(state.cart),sum=calcSummary(vals);$('cashierBody').innerHTML=`<div class="pos-layout"><section><div class="category-row">${cats}</div><div class="pos-menu-grid">${items.map(i=>`<button class="pos-item ${i.out_of_stock?'disabled-note':''}" onclick="addQty(${i.id},1)"><img src="${i.image_url||''}" onerror="this.style.display='none'"><b>${i.name}</b><span class="muted">${i.category}</span><div class="between"><strong>${money(i.price)}</strong>${i.out_of_stock?'<span class="badge danger">Out</span>':'<span class="badge ok">Add</span>'}</div></button>`).join('')}</div></section><aside class="pos-cart card"><h2 style="margin-top:0">Cart (${cartQty()})</h2>${vals.map(x=>`<div class="pos-qty-row"><div><b>${x.item.name}</b><br><span class="muted">${money(x.item.price)} x ${x.qty}</span></div><div class="qty"><button onclick="addQty(${x.item.id},-1)">−</button><b>${x.qty}</b><button onclick="addQty(${x.item.id},1)">+</button></div></div>`).join('')||'<p class="muted">Tap item images to add.</p>'}${summaryHtml(sum,'Order Value')}<label>Payment Method</label><select id="payMethod"><option>Cash</option><option>UPI</option><option>Card</option></select><button class="btn accent" style="margin-top:12px" onclick="placeOrder('cashier')">Collect Payment & Print Receipt</button><button class="btn ghost" style="margin-top:10px" onclick="state.cart={};saveCart();renderCashierBody()">Clear Cart</button></aside></div>`}
function renderCashierConfirmation(o){$('cashierBody').innerHTML=`<div class="pos-layout"><section>${orderQrCard(o,true)}</section><aside class="card pos-cart"><h2>Payment Collected</h2><p class="muted">QR receipt includes order summary, quantity, price, GST/other taxes and payment reference.</p><button class="btn secondary" onclick="printReceipt(${o.id})">Print QR Receipt</button><button class="btn" style="margin-top:10px" onclick="state.cart={};saveCart();renderCashierBody()">New Walk-in Order</button></aside></div>`}

function renderDelivery(){
  document.getElementById('root').innerHTML=`<main class="delivery-shell"><header class="delivery-head"><div><h1>Delivery / Pickup Fulfilment</h1><p class="muted">Customer presents the QR receipt. Scan or enter the order number / QR token to hand over food and mark it fulfilled.</p></div><button class="btn ghost" style="width:auto" onclick="logout()">Logout</button></header><section class="delivery-grid"><div class="card delivery-card"><h2>Validate Customer QR</h2><p class="hint">Use a barcode scanner connected as keyboard input, or paste/type the order number printed on the QR receipt.</p><input id="deliveryQrInput" class="big-input" placeholder="Scan QR / enter order number" autofocus onkeydown="if(event.key==='Enter') deliveryValidate()"><button class="btn secondary big-btn" onclick="deliveryValidate()">Validate & Mark Fulfilled</button><button class="btn ghost" style="margin-top:10px" onclick="$('deliveryQrInput').value='';$('deliveryResult').innerHTML=''">Clear</button></div><div id="deliveryResult" class="card delivery-result"><h2>Awaiting QR</h2><p class="muted">After validation, order items, quantity, payment and fulfilment status will be shown here.</p></div></section></main>`
}
async function deliveryValidate(){
  let q=($('deliveryQrInput')?.value||'').trim();
  if(!q)return toast('Scan or enter the customer QR / order number');
  try{
    let d=await api('/api/qr/validate',{method:'POST',body:JSON.stringify({token:state.token,qr_token:q})});
    let o=d.order||{};
    $('deliveryResult').innerHTML=`<h2>${d.ok?'Order Fulfilled':'Validation Failed'}</h2><p class="${d.ok?'badge ok':'badge danger'}" style="display:inline-block">${d.message}</p>${o.id?`<div style="margin-top:14px">${orderSummaryHtml(o)}<div class="card" style="background:#f7fff9"><div class="between"><span>Fulfilment Status</span><b>${o.order_status}</b></div><div class="between muted"><span>QR Status</span><span>${o.qr_status||'validated'}</span></div></div></div>`:''}`;
    if(d.ok) toast('Food delivered. Order marked fulfilled.');
  }catch(e){toast(e.message||'Validation failed')}
}

function renderAdminShell(){document.getElementById('root').innerHTML=`<div class="admin-shell"><aside class="admin-side"><h2>Truflux FoodFlow</h2><div class="admin-nav">${adminNavButtons()}</div><button class="btn ghost" style="margin-top:18px" onclick="logout()">Logout</button></aside><div class="admin-mobile-header">${adminNavButtons()}</div><main class="admin-main"><div class="admin-top"><div><h1 id="adminTitle">Operations Dashboard</h1><p class="muted">Responsive admin for website and mobile devices.</p></div><a class="btn ghost" style="width:auto;text-decoration:none" href="/app">Open Consumer App</a></div><div id="adminBody"></div></main></div>`;adminShow('dashboard')}
function adminNavButtons(){return `<button data-admin="dashboard" onclick="adminShow('dashboard')">Dashboard</button><button data-admin="menu" onclick="adminShow('menu')">Menu</button><button data-admin="orders" onclick="adminShow('orders')">Orders</button><button data-admin="kitchen" onclick="adminShow('kitchen')">Kitchen Board</button><button data-admin="sku" onclick="adminShow('sku')">Central Kitchen Demand</button><button data-admin="dateReport" onclick="adminShow('dateReport')">Order Date Report</button><button data-admin="config" onclick="adminShow('config')">Configuration</button><button data-admin="users" onclick="adminShow('users')">Users</button>`}
function adminActive(k,title){document.querySelectorAll('[data-admin]').forEach(b=>b.classList.toggle('active',b.dataset.admin===k));$('adminTitle').textContent=title}
async function adminShow(k){if(k==='dashboard')return adminDashboard();if(k==='menu')return adminMenu();if(k==='orders')return adminOrders();if(k==='kitchen')return adminKitchen();if(k==='sku')return adminSku();if(k==='dateReport')return adminDateReport();if(k==='config')return adminConfig();if(k==='users')return adminUsers()}
async function adminDashboard(){adminActive('dashboard','Operations Dashboard');let d=await api('/api/admin/dashboard?token='+encodeURIComponent(state.token));$('adminBody').innerHTML=`<div class="card"><div class="between" style="gap:14px;align-items:center"><div><h3 style="margin:0">Demo / Test Data</h3><p class="muted">Create or refresh 5 menu items in each category for every active store.</p></div><button class="btn secondary" style="width:auto;min-width:260px" onclick="createTestData()">Create Test Data</button></div></div><div class="stats-grid"><div class="card"><span class="muted">Orders</span><h1>${d.stats.orders_today}</h1></div><div class="card"><span class="muted">Sales</span><h1>${money(d.stats.sales_today)}</h1></div><div class="card"><span class="muted">Kitchen Pending</span><h1>${d.stats.pending_kitchen}</h1></div><div class="card"><span class="muted">Mobile/Kiosk/Cashier</span><h1>${d.stats.mobile_orders}/${d.stats.kiosk_orders}/${d.stats.cashier_orders}</h1></div></div><div class="admin-grid">${d.by_store.map(s=>`<div class="card"><div class="between"><b>${s.store}</b><b>${money(s.sales)}</b></div><p class="muted">${s.orders} orders</p></div>`).join('')}</div>`}
async function createTestData(){if(!confirm('Create or refresh 5 items in each category for every active store?'))return;let d=await api('/api/admin/test-data/menu?token='+encodeURIComponent(state.token),{method:'POST'});toast(d.message+' Inserted '+d.inserted+', refreshed '+d.updated+'.');await loadMenu();if(document.querySelector('[data-admin=menu].active')) adminMenu(); else adminDashboard()}
async function adminMenu(){adminActive('menu','Menu Management');let d=await api('/api/admin/menu?token='+encodeURIComponent(state.token));$('adminBody').innerHTML=`<div class="card"><div class="between" style="gap:12px"><h3>Add Menu Item</h3><button class="btn secondary" style="width:auto" onclick="createTestData()">Create Test Data: 5 per Category</button></div><div class="admin-grid"><div><label>Store</label><select id="mStore">${state.stores.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select><label>Name</label><input id="mName"><label>SKU</label><input id="mSku"><label>Category</label><input id="mCat"><label>Price</label><input id="mPrice" type="number"></div><div><label>Image URL</label><input id="mImgUrl" placeholder="https://..."><label>Or upload image file</label><input id="mImgFile" type="file" accept="image/*"><label>Description</label><textarea id="mDesc"></textarea><button class="btn secondary" style="margin-top:12px" onclick="adminAddItem()">Add Item</button></div></div></div><table class="table"><thead><tr><th>Image</th><th>Item</th><th>Store</th><th>Price</th><th>Status</th><th>Action</th></tr></thead><tbody>${d.items.map(i=>`<tr><td><img class="preview-img" src="${i.image_url||''}" onerror="this.style.display='none'"></td><td><b>${i.name}</b><br><span class="muted">${i.sku} • ${i.category}</span></td><td>${state.stores.find(s=>s.id==i.store_id)?.area||i.store_id}</td><td>${money(i.price)}</td><td>${i.out_of_stock?'<span class="badge danger">Out</span>':'<span class="badge ok">In stock</span>'}</td><td><button class="btn small ghost" onclick='adminToggleStock(${JSON.stringify(i).replaceAll("'","&#39;")})'>${i.out_of_stock?'In Stock':'Out of Stock'}</button><button class="btn small danger" style="margin-top:6px" onclick="adminRemove(${i.id})">Remove</button></td></tr>`).join('')}</tbody></table>`}
function fileToDataUrl(input){return new Promise(res=>{let f=input.files&&input.files[0];if(!f)return res('');let r=new FileReader();r.onload=()=>res(r.result);r.readAsDataURL(f)})}
async function adminAddItem(){let img=(await fileToDataUrl($('mImgFile')))||$('mImgUrl').value;await api('/api/admin/menu',{method:'POST',body:JSON.stringify({token:state.token,store_id:Number($('mStore').value),name:$('mName').value,sku:$('mSku').value,category:$('mCat').value,price:Number($('mPrice').value||0),image_url:img,description:$('mDesc').value,enabled:true,out_of_stock:false})});toast('Item added');await loadMenu();adminMenu()}
async function adminToggleStock(i){i.out_of_stock=i.out_of_stock?false:true;await api('/api/admin/menu',{method:'PUT',body:JSON.stringify({token:state.token,id:i.id,store_id:i.store_id,name:i.name,sku:i.sku,category:i.category,price:i.price,image_url:i.image_url||'',description:i.description||'',enabled:!!i.enabled,out_of_stock:!!i.out_of_stock,is_combo:!!i.is_combo,cross_sell_ids:safeJson(i.cross_sell_ids),upsell_ids:safeJson(i.upsell_ids)})});adminMenu()}
async function adminRemove(id){await api('/api/admin/menu/'+id+'?token='+encodeURIComponent(state.token),{method:'DELETE'});toast('Removed from menu');await loadMenu();adminMenu()}
async function adminOrders(){adminActive('orders','Orders');let d=await api('/api/admin/orders?token='+encodeURIComponent(state.token));$('adminBody').innerHTML=`<table class="table"><thead><tr><th>Order</th><th>Store</th><th>Source</th><th>Total</th><th>Payment</th><th>Status</th></tr></thead><tbody>${d.orders.map(o=>`<tr><td>${o.order_no}</td><td>${o.store_name}</td><td>${o.source}</td><td>${money(o.total)}</td><td>${o.payment_status}</td><td>${o.order_status}</td></tr>`).join('')}</tbody></table>`}
async function adminKitchen(){adminActive('kitchen','Kitchen Order Board');let d=await api('/api/kitchen-board');$('adminBody').innerHTML=`<div class="admin-grid">${d.orders.map(o=>`<div class="card"><div class="between"><b>${o.order_no}</b><span class="badge ok">${o.source}</span></div><p class="muted">${o.store_name} • ${o.order_status}</p>${o.items.map(i=>`<div class="order-line"><span>${i.name}</span><b>x${i.quantity}</b></div>`).join('')}<div class="admin-grid"><button class="btn small" onclick="setOrderStatus(${o.id},'preparing')">Preparing</button><button class="btn small secondary" onclick="setOrderStatus(${o.id},'ready')">Ready</button></div><button class="btn small ghost" style="margin-top:8px" onclick="setOrderStatus(${o.id},'completed')">Completed</button></div>`).join('')||'<div class="card">No live orders</div>'}</div><div class="card"><h3>QR Pickup Validation</h3><input id="qrTokenInput" placeholder="Scan / paste QR token"><button class="btn secondary" style="margin-top:10px" onclick="validateQR()">Validate Pickup</button></div>`}
async function setOrderStatus(id,status){await api('/api/orders/status',{method:'POST',body:JSON.stringify({order_id:id,status})});adminKitchen()}
async function validateQR(){let d=await api('/api/qr/validate',{method:'POST',body:JSON.stringify({token:state.token,qr_token:$('qrTokenInput').value})});toast(d.message);adminKitchen()}
async function adminSku(){
  adminActive('sku','Central Kitchen Demand by Date & Location');
  let today=new Date().toISOString().slice(0,10);
  let from=$('ckFrom')?.value||today;
  let to=$('ckTo')?.value||today;
  let storeId=$('ckStore')?.value||'';
  let qs='token='+encodeURIComponent(state.token)+'&from_date='+encodeURIComponent(from)+'&to_date='+encodeURIComponent(to)+(storeId?'&store_id='+encodeURIComponent(storeId):'');
  let d=await api('/api/admin/central-kitchen-demand?'+qs);
  let ai=await api('/api/ai/insights?token='+encodeURIComponent(state.token));
  let g=d.grand||{};
  $('adminBody').innerHTML=`<div class="card"><h3>Production Demand Filter</h3><p class="hint">Central kitchen can plan cooking from confirmed paid orders grouped by menu item/SKU, date and store location.</p><div class="admin-grid"><div><label>From Date</label><input id="ckFrom" type="date" value="${d.from_date}"></div><div><label>To Date</label><input id="ckTo" type="date" value="${d.to_date}"></div><div><label>Location / Store</label><select id="ckStore"><option value="">All Locations</option>${d.stores.map(s=>`<option value="${s.id}" ${String(d.store_id||'')===String(s.id)?'selected':''}>${s.area} - ${s.name}</option>`).join('')}</select></div><div style="display:flex;align-items:end;gap:10px"><button class="btn secondary" onclick="adminSku()">Run Demand Report</button><a class="btn ghost" style="text-decoration:none;text-align:center" href="/api/admin/central-kitchen-demand.csv?${qs}">Download CSV</a></div></div></div><div class="stats-grid"><div class="card"><span class="muted">Confirmed Dish Demand</span><h1>${g.demand_qty||0}</h1></div><div class="card"><span class="muted">Paid Orders</span><h1>${g.order_count||0}</h1></div><div class="card"><span class="muted">Gross Item Value</span><h1>${money(g.gross_value||0)}</h1></div><div class="card"><span class="muted">Locations</span><h1>${(d.by_location||[]).length}</h1></div></div><div class="admin-grid"><div class="card"><h3>AI Suggested Cooking Plan</h3>${(d.production_plan||[]).map(p=>`<div class="order-line"><span>${p.item_name}<br><span class="muted">${p.sku} • confirmed ${p.confirmed_qty} + buffer ${p.suggested_buffer_qty}</span></span><b>${p.suggested_cook_qty}</b></div>`).join('')||'<p class="hint">No confirmed demand yet for the selected date range.</p>'}</div><div class="card"><h3>AI Notes</h3>${ai.recommendations.map(r=>`<p class="badge" style="white-space:normal">${r}</p>`).join('')}<p class="hint">Buffer is currently a prototype 10% production planning uplift and can be made configurable.</p></div></div><div class="card"><h3>Demand by Date, Location and Menu Item</h3><table class="table"><thead><tr><th>Date</th><th>Location</th><th>SKU</th><th>Item</th><th>Category</th><th>Demand Qty</th><th>Orders</th><th>Value</th></tr></thead><tbody>${(d.detail||[]).map(r=>`<tr><td><b>${r.demand_date}</b></td><td>${r.location}<br><span class="muted">${r.store_name}</span></td><td>${r.sku}</td><td>${r.item_name}</td><td>${r.category||''}</td><td><b>${r.demand_qty}</b></td><td>${r.order_count}</td><td>${money(r.gross_value)}</td></tr>`).join('')||'<tr><td colspan="8">No confirmed paid orders found for the selected date range.</td></tr>'}</tbody></table></div><div class="admin-grid"><div class="card"><h3>Location Summary</h3>${(d.by_location||[]).map(r=>`<div class="order-line"><span>${r.location}<br><span class="muted">${r.store_name}</span></span><b>${r.demand_qty}</b></div>`).join('')||'<p class="hint">No location demand found.</p>'}</div><div class="card"><h3>Item Summary</h3>${(d.by_item||[]).slice(0,12).map(r=>`<div class="order-line"><span>${r.item_name}<br><span class="muted">${r.sku} • ${r.category||''}</span></span><b>${r.demand_qty}</b></div>`).join('')||'<p class="hint">No item demand found.</p>'}</div></div>`
}


async function adminDateReport(){adminActive('dateReport','Consolidated Order Report by Date');let today=new Date().toISOString().slice(0,10);let from=$('dateFrom')?.value||today;let to=$('dateTo')?.value||today;let d=await api('/api/admin/order-date-report?token='+encodeURIComponent(state.token)+'&from_date='+encodeURIComponent(from)+'&to_date='+encodeURIComponent(to));let g=d.grand||{};$('adminBody').innerHTML=`<div class="card"><div class="admin-grid"><div><label>From Date</label><input id="dateFrom" type="date" value="${d.from_date}"></div><div><label>To Date</label><input id="dateTo" type="date" value="${d.to_date}"></div><div style="display:flex;align-items:end;gap:10px"><button class="btn secondary" onclick="adminDateReport()">Run Report</button><a class="btn ghost" style="text-decoration:none;text-align:center" href="/api/admin/order-date-report.csv?token=${encodeURIComponent(state.token)}&from_date=${encodeURIComponent(d.from_date)}&to_date=${encodeURIComponent(d.to_date)}">Download CSV</a></div></div></div><div class="stats-grid"><div class="card"><span class="muted">Total Orders</span><h1>${g.orders||0}</h1></div><div class="card"><span class="muted">Paid Orders</span><h1>${g.paid_orders||0}</h1></div><div class="card"><span class="muted">Dishes Sold</span><h1>${g.dishes||0}</h1></div><div class="card"><span class="muted">Total Value</span><h1>${money(g.total_value||0)}</h1></div></div><table class="table"><thead><tr><th>Date</th><th>Total Orders</th><th>Paid</th><th>Unpaid</th><th>Mobile</th><th>Kiosk</th><th>Cashier</th><th>Dishes</th><th>Subtotal</th><th>Tax</th><th>Total</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td><b>${r.order_date}</b></td><td>${r.total_orders}</td><td>${r.paid_orders}</td><td>${r.unpaid_orders}</td><td>${r.mobile_orders}</td><td>${r.kiosk_orders}</td><td>${r.cashier_orders}</td><td>${r.dishes}</td><td>${money(r.subtotal)}</td><td>${money(r.tax_total)}</td><td><b>${money(r.total_value)}</b></td></tr>`).join('')||'<tr><td colspan="11">No orders found for the selected date range.</td></tr>'}</tbody></table>`}

function adminConfig(){adminActive('config','Desktop Configuration');let t=state.config.theme,f=state.config.features,tx=state.config.taxes||{enabled:true,lines:[]};let l0=tx.lines?.[0]||{label:'GST',rate:5,enabled:true},l1=tx.lines?.[1]||{label:'Other Tax',rate:0,enabled:false};$('adminBody').innerHTML=`<div class="admin-grid"><div class="card"><h3>Theme / Color Configuration</h3><label>App Name</label><input id="cfgName" value="${t.app_name||''}"><label>Primary Color</label><input id="cfgPrimary" value="${t.primary_color||''}"><label>Secondary Color</label><input id="cfgSecondary" value="${t.secondary_color||''}"><label>Accent Color</label><input id="cfgAccent" value="${t.accent_color||''}"><label>Background Color</label><input id="cfgBg" value="${t.background_color||''}"><label>App/Kiosk Advertising Image URL</label><input id="cfgAdUrl" value="${t.ad_banner_url||''}" placeholder="https://..."><label>Advertising Title</label><input id="cfgAdTitle" value="${t.ad_banner_title||''}"><label>Advertising Text</label><input id="cfgAdText" value="${t.ad_banner_text||''}"><button class="btn secondary" style="margin-top:12px" onclick="saveTheme()">Save Theme & Advertising</button></div><div class="card"><h3>GST / Tax Configuration</h3><label class="switch"><span>Enable Taxes</span><input id="taxEnabled" type="checkbox" ${tx.enabled!==false?'checked':''}></label><label>Tax Line 1 Text</label><input id="tax1Label" value="${l0.label||'GST'}"><label>Tax Line 1 Value %</label><input id="tax1Rate" type="number" step="0.01" value="${l0.rate||0}"><label class="switch"><span>Enable Tax Line 1</span><input id="tax1Enabled" type="checkbox" ${l0.enabled!==false?'checked':''}></label><label>Tax Line 2 Text</label><input id="tax2Label" value="${l1.label||'Other Tax'}"><label>Tax Line 2 Value %</label><input id="tax2Rate" type="number" step="0.01" value="${l1.rate||0}"><label class="switch"><span>Enable Tax Line 2</span><input id="tax2Enabled" type="checkbox" ${l1.enabled?'checked':''}></label><button class="btn secondary" style="margin-top:12px" onclick="saveTaxes()">Save Tax Configuration</button><p class="hint">The configured tax text and value appear in mobile, kiosk and cashier receipts.</p></div><div class="card"><h3>Feature Switches</h3><div class="config-grid">${Object.keys(f).map(k=>`<label class="switch"><span>${k.replaceAll('_',' ')}</span><input type="checkbox" data-feature="${k}" ${f[k]?'checked':''}></label>`).join('')}</div><button class="btn" style="margin-top:12px" onclick="saveFeatures()">Save Features</button><p class="hint">All major modules can be enabled or disabled from the desktop admin version. Mobile admin adapts for smaller devices.</p></div></div>`}
async function saveTheme(){let d=await api('/api/admin/theme',{method:'POST',body:JSON.stringify({token:state.token,app_name:$('cfgName').value,primary_color:$('cfgPrimary').value,secondary_color:$('cfgSecondary').value,accent_color:$('cfgAccent').value,background_color:$('cfgBg').value,logo_url:'',ad_banner_url:$('cfgAdUrl')?.value||'',app_banner_url:$('cfgAdUrl')?.value||'',kiosk_banner_url:$('cfgAdUrl')?.value||'',ad_banner_title:$('cfgAdTitle')?.value||'',ad_banner_text:$('cfgAdText')?.value||''})});state.config.theme=d.theme;applyTheme(d.theme);toast('Theme saved')}
async function saveFeatures(){let features={};document.querySelectorAll('[data-feature]').forEach(x=>features[x.dataset.feature]=x.checked);let d=await api('/api/admin/features',{method:'POST',body:JSON.stringify({token:state.token,features})});state.config.features=d.features;toast('Features saved')}async function saveTaxes(){let taxes={enabled:$('taxEnabled').checked,lines:[{label:$('tax1Label').value||'GST',rate:Number($('tax1Rate').value||0),enabled:$('tax1Enabled').checked},{label:$('tax2Label').value||'Other Tax',rate:Number($('tax2Rate').value||0),enabled:$('tax2Enabled').checked}]};let d=await api('/api/admin/taxes',{method:'POST',body:JSON.stringify({token:state.token,taxes})});state.config.taxes=d.taxes;toast('Tax configuration saved')}
async function adminUsers(){adminActive('users','User Management');let d=await api('/api/admin/users?token='+encodeURIComponent(state.token));$('adminBody').innerHTML=`<table class="table"><thead><tr><th>Username / Phone</th><th>Name</th><th>Email</th><th>Role</th></tr></thead><tbody>${d.users.map(u=>`<tr><td>${u.mobile}</td><td>${u.name||''}</td><td>${u.email||''}</td><td>${u.role}</td></tr>`).join('')}</tbody></table>`}

function setupInfiniteScroll(){if(window._ffScrollBound)return;window._ffScrollBound=true;window.addEventListener('scroll',()=>{if(state.mode!=='consumer')return;let menu=$('menu');if(!menu||!menu.classList.contains('active'))return;let all=state.menu.filter(i=>state.cat==='All'||i.category===state.cat);if(state.visibleCount>=all.length)return;if(window.innerHeight+window.scrollY>document.body.offsetHeight-260){state.visibleCount+=8;renderMenu();}})}

setupInfiniteScroll();
setInterval(ensureHomeButton,700);
boot().then(ensureHomeButton).catch(e=>{console.error(e); toast(e.message||'Startup error'); ensureHomeButton();});
